import type { BankQuestion } from "@/lib/bank";

/** Percentage (Quantitative Aptitude): 143 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"quant-percentage-1","question":"A price rises by 20% and then falls by 20%. The net change is:","options":["No change","4% decrease","4% increase","2% decrease"],"answer":1,"explanation":"Net change = −x²/100 = −400/100 = −4%.","difficulty":"hard"},
  {"id":"quant-percentage-2","question":"12.5% expressed as a fraction is:","options":["1/4","1/6","1/8","1/12"],"answer":2,"explanation":"12.5% = 12.5/100 = 1/8.","difficulty":"easy"},
  {"id":"quant-percentage-3","question":"If 40% of a number is 80, the number is:","options":["120","160","200","320"],"answer":2,"explanation":"Number = 80 ÷ 40 × 100 = 200.","difficulty":"moderate"},
  {"id":"quant-percentage-4","question":"In an election between two candidates, the winner got 60% of the votes and won by 1,200 votes. The total number of votes was:","options":["3,000","4,800","6,000","7,200"],"answer":2,"explanation":"The margin is 60% − 40% = 20% of the votes, so 20% = 1,200 and total = 6,000.","difficulty":"very-hard"},
  {"id":"quant-percentage-5","question":"If 20% of a number is 60, the number is:","options":["120","240","300","360"],"answer":2,"explanation":"20% × N = 60 ⇒ N = 60 × 5 = 300.","difficulty":"easy","source":"SSC CHSL · RRB Group D"},
  {"id":"quant-percentage-6","question":"A number is increased by 20% and then decreased by 20%. The net change is:","options":["No change","4% increase","4% decrease","2% decrease"],"answer":2,"explanation":"1.2 × 0.8 = 0.96, a 4% decrease. Successive x% up and x% down always loses x²/100 %.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-percentage-7","question":"In an election between two candidates, the winner got 60% of the votes and won by 1,200 votes. Total votes polled:","options":["3,000","4,800","6,000","7,200"],"answer":2,"explanation":"Margin = 60% − 40% = 20% of total = 1,200 ⇒ total = 6,000.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-percentage-8","question":"The price of sugar rises by 25%. By what percent must a family cut consumption to keep spending unchanged?","options":["20%","25%","30%","33⅓%"],"answer":0,"explanation":"Cut = 25/(100 + 25) × 100 = 20%.","difficulty":"very-hard","source":"SSC CGL · SBI Clerk"},
  {"id":"quant-percentage-9","question":"What percent of 2 kg is 250 g?","options":["12.5%","25%","8%","1.25%"],"answer":0,"explanation":"250 g ÷ 2,000 g = 1/8 = 12.5%. Both quantities must be in the same unit first; 25% is the slip of using 1 kg as the base.","difficulty":"easy","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-percentage-10","question":"If 35% of a number exceeds 25% of the same number by 14, the number is:","options":["140","100","280","56"],"answer":0,"explanation":"35% − 25% = 10% of the number = 14, so the number = 140. Check: 35% of 140 = 49 and 25% of 140 = 35, difference 14.","difficulty":"easy","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-percentage-11","question":"A's salary is 25% more than B's. B's salary is less than A's by:","options":["33⅓%","20%","75%","25%"],"answer":1,"explanation":"Let B = 100, so A = 125. B is less than A by 25 on a base of 125 = 20%. The base changes from B to A, so the answer is not 25%.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"quant-percentage-12","question":"The population of a town grows 10% every year. If the present population is 12,100, what was it two years ago?","options":["10,890","9,900","9,680","10,000"],"answer":3,"explanation":"P × 1.1 × 1.1 = 12,100, so P = 12,100/1.21 = 10,000. Subtracting 10% twice (12,100 → 10,890 → 9,801) is the wrong-base slip.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-percentage-13","question":"A student scoring 30% fails by 20 marks, while a student scoring 50% gets 30 marks more than the pass mark. The pass mark is:","options":["95","250","75","125"],"answer":0,"explanation":"The gap between 30% and 50% is 20 + 30 = 50 marks, so 20% = 50 and maximum marks = 250. Pass mark = 30% of 250 + 20 = 75 + 20 = 95.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-percentage-14","question":"Rohit spends 40% of his income on rent and 30% of the remainder on food. If he saves ₹8,400, his income is:","options":["₹12,000","₹20,000","₹28,000","₹14,000"],"answer":1,"explanation":"After rent 60% remains; after food 70% of that remains, i.e. 0.6 × 0.7 = 42% of income = ₹8,400. Income = 8,400/0.42 = ₹20,000. Treating food as 30% of the whole income (saving 30%) gives the wrong ₹28,000.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"quant-percentage-15","question":"The price of petrol was raised by 20% and later by another 25%. By what percent must a motorist cut consumption so that his expenditure stays the same?","options":["40%","45%","50%","33⅓%"],"answer":3,"explanation":"Net price factor = 1.2 × 1.25 = 1.5. Consumption must become 1/1.5 = 2/3 of the original, a cut of 1/3 = 33⅓%. Adding the rises to 45% and cutting 45% are both wrong.","difficulty":"hard","source":"SSC CGL · CDS"},
  {"id":"quant-percentage-16","question":"In an examination 65% of candidates passed in English, 55% passed in Mathematics and 30% failed in both. If 150 candidates passed in both subjects, the total number of candidates is:","options":["350","300","250","400"],"answer":1,"explanation":"Passed in at least one = 100 − 30 = 70%. Passed in both = 65 + 55 − 70 = 50% = 150, so total = 300.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-percentage-17","question":"In an election between two candidates, 15% of the listed voters did not vote and 350 votes were declared invalid. The winner got 60% of the valid votes and won by 1,800 votes. The number of voters on the list was:","options":["11,000","9,000","9,350","10,500"],"answer":0,"explanation":"The margin is 60% − 40% = 20% of valid votes = 1,800, so valid votes = 9,000 and votes cast = 9,000 + 350 = 9,350. That is 85% of the list, so the list has 9,350/0.85 = 11,000 voters.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-percentage-18","question":"A number is increased by x% and the result is then decreased by x%. If the final number is 4% less than the original, x is:","options":["4","40","20","2"],"answer":2,"explanation":"A rise and fall of x% each gives a net change of −x²/100 %. So x²/100 = 4, x² = 400, x = 20. Check: 100 → 120 → 96.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-percentage-19","question":"The price of rice rose by 20%, but a family cut its consumption so that its expenditure rose by only 8%. The consumption fell by:","options":["20%","12%","10%","8%"],"answer":2,"explanation":"Expenditure = price × quantity, so 1.2 × q = 1.08 gives q = 0.9, a fall of 10%. The slip 20% − 8% = 12% ignores that the percentages act on different bases.","difficulty":"hard","source":"SSC CGL · SBI PO"},
  {"id":"quant-percentage-20","question":"A's income is 20% more than B's and B's income is 25% less than C's. A's income as a percentage of C's is:","options":["85%","95%","105%","90%"],"answer":3,"explanation":"Let C = 100; B = 75; A = 1.2 × 75 = 90. So A is 90% of C. Simply adding +20% and −25% to get 95% is the wrong-base error.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-percentage-21","question":"In a college 60% of the students are boys. 20% of the boys and 30% of the girls come from outside the state. If 480 students come from outside the state, the total strength of the college is:","options":["1,600","2,000","1,920","2,400"],"answer":1,"explanation":"Outside-state fraction = 0.6 × 0.2 + 0.4 × 0.3 = 0.12 + 0.12 = 0.24 of the total. Total = 480/0.24 = 2,000. Using the average 25% of the two rates gives the wrong 1,920.","difficulty":"very-hard","source":"SSC CGL · SBI PO"},
  {"id":"quant-percentage-22","question":"40 litres of a solution contains 15% alcohol. How much pure alcohol must be added so that the solution contains 32% alcohol?","options":["6.8 litres","8 litres","12 litres","10 litres"],"answer":3,"explanation":"Alcohol now = 6 L. Adding x L of pure alcohol: 6 + x = 0.32(40 + x), so 6 + x = 12.8 + 0.32x, 0.68x = 6.8, x = 10. Check: 16/50 = 32%. The slip 0.17 × 40 = 6.8 ignores that the total also rises.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-percentage-23","question":"How many of the following statements are correct?\n1. A number increased by 10% and then decreased by 10% falls by 1% overall.\n2. If A is 50% more than B, then B is 50% less than A.\n3. 20% of 30% of a number equals 6% of that number.\n4. If a price rises by 25%, cutting consumption by 20% keeps the expenditure unchanged.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"1 is true (1.1 × 0.9 = 0.99). 2 is false: B is 50/150 = 33⅓% less than A. 3 is true (0.2 × 0.3 = 0.06). 4 is true (1.25 × 0.8 = 1). So three statements are correct.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"quant-percentage-24","question":"A 20% fall in the price of wheat lets a housewife buy 5 kg more for ₹400. The reduced price per kg is:","options":["₹20","₹16","₹25","₹12"],"answer":1,"explanation":"With the new price being 80% of the old, ₹400 buys 5/4 of the old quantity, so the extra 1/4 = 5 kg and the old quantity was 20 kg at ₹20/kg. Reduced price = 0.8 × 20 = ₹16. ₹20 is the original price, not the reduced one.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-percentage-25","question":"A man's salary rose by 10% in 2023, by 20% in 2024 and was cut by 25% in 2025. Compared with his 2022 salary, his 2025 salary is:","options":["5% less","5% more","1% less","1% more"],"answer":2,"explanation":"Net factor = 1.1 × 1.2 × 0.75 = 0.99, so the salary is 1% less. Adding the percentages (10 + 20 − 25 = +5%) ignores compounding.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-percentage-26","question":"In an election among three candidates A, B and C, A got 40% of the votes and B got 35%. If A defeated C by 4,500 votes, the number of votes B received was:","options":["7,500","9,000","10,500","12,000"],"answer":2,"explanation":"C got 100 − 40 − 35 = 25%. A − C = 15% of total = 4,500, so total = 30,000 and B = 35% of 30,000 = 10,500.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-percentage-27","question":"A firm has 1,000 employees of whom 60% are men. 50% of the men and 25% of the women are graduates. What percent of the non-graduate employees are women?","options":["50%","45%","60%","40%"],"answer":0,"explanation":"Men 600, women 400. Non-graduate men = 50% of 600 = 300; non-graduate women = 75% of 400 = 300. Women form 300/600 = 50% of non-graduates. Using 40% (women's share of all staff) is the wrong base.","difficulty":"very-hard","source":"SSC CGL · SBI PO"},
  {"id":"quant-percentage-28","question":"In a test Riya scored 60% and Priya scored 75% of the maximum marks, and Priya's score exceeded Riya's by 45 marks. If the pass mark is 40%, by how many marks did Riya clear the pass mark?","options":["120","45","75","60"],"answer":3,"explanation":"15% of the maximum = 45, so maximum marks = 300. Riya scored 180, the pass mark is 120, so she cleared it by 60 marks.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id": "quant-percentage-29", "question": "What is 15% of 25% of 1,600?", "options": ["64", "60", "40", "600"], "answer": 1, "explanation": "25% of 1,600 = 400; 15% of 400 = 60. Equivalently 0.15 × 0.25 × 1,600 = 60.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "quant-percentage-30", "question": "A's income is 40% less than B's. By what percent is B's income more than A's?", "options": ["66⅔%", "40%", "60%", "28⅓%"], "answer": 0, "explanation": "Let B = 100, so A = 60. B exceeds A by 40, which is 40/60 × 100 = 66⅔% of A. 40% uses B as the base by mistake.", "difficulty": "moderate", "source": "SSC CGL"},
  {"id": "quant-percentage-31", "question": "The price of an item rises by 30% and a customer buys 10% less of it. By what percent does his expenditure change?", "options": ["20% increase", "3% increase", "13% increase", "17% increase"], "answer": 3, "explanation": "Expenditure = price × quantity = 1.30 × 0.90 = 1.17 of the original, a 17% increase. 20% wrongly subtracts 30 − 10 directly.", "difficulty": "moderate", "source": "SSC CGL"},
  {"id": "quant-percentage-32", "question": "Ravi spends 75% of his income. His income rises by 20% and his expenditure by 10%. By what percent do his savings increase?", "options": ["30%", "10%", "50%", "40%"], "answer": 2, "explanation": "Income 100, spending 75, saving 25. New income 120, new spending 82.5, new saving 37.5. Increase = 12.5/25 = 50%.", "difficulty": "hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-percentage-33", "question": "A town's population rose 20% in the first year, fell 10% in the second and rose 20% in the third, reaching 38,880. What was it at the start?", "options": ["32,400", "30,000", "27,000", "31,104"], "answer": 1, "explanation": "Overall factor = 1.2 × 0.9 × 1.2 = 1.296. Initial = 38,880 ÷ 1.296 = 30,000. 32,400 undoes only the last rise; 31,104 subtracts 20% of the final figure instead of dividing.", "difficulty": "hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-percentage-34", "question": "A's salary is 25% more than B's, and B's salary is 20% more than C's. If A earns ₹4,500 more than C, what is C's salary?", "options": ["₹9,000", "₹10,000", "₹10,800", "₹7,500"], "answer": 0, "explanation": "A = 1.25 × 1.2 × C = 1.5C, so A − C = 0.5C = 4,500 and C = ₹9,000. Taking 25% + 20% = 45% gives the slip ₹10,000.", "difficulty": "hard", "source": "SSC CGL"},
  {"id": "quant-percentage-35", "question": "Ram spends 20% of his income on rent, 30% of the remainder on his children's education and 25% of what is then left on food. He is left with ₹12,600. What is his income?", "options": ["₹50,400", "₹25,200", "₹28,000", "₹30,000"], "answer": 3, "explanation": "Left = income × 0.80 × 0.70 × 0.75 = 0.42 × income. Income = 12,600 ÷ 0.42 = ₹30,000. Subtracting 20 + 30 + 25 = 75% of the whole gives ₹50,400, the common slip.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-percentage-36", "question": "The length of a rectangle is increased by 25%. By what percent must the breadth be cut to keep the area unchanged, and what happens to the area if the breadth is cut by only 10%?", "options": ["25%; area rises by 15%", "20%; area rises by 15%", "20%; area rises by 12.5%", "25%; area rises by 12.5%"], "answer": 2, "explanation": "For equal area, breadth factor = 1/1.25 = 0.8, a 20% cut. With a 10% cut, area factor = 1.25 × 0.9 = 1.125, a 12.5% increase. 25% − 10% = 15% is the additive slip.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-percentage-37", "question": "How many of the following statements are correct? 1. If x is 25% more than y, then y is 20% less than x. 2. Successive increases of 10% and 20% equal a single increase of 32%. 3. If a price falls by 20%, consumption can rise by 25% with no change in spending. 4. 0.5% of 400 is 20.", "options": ["Only two", "Only three", "All four", "Only one"], "answer": 1, "explanation": "1: y = x/1.25 = 0.8x ✓. 2: 1.1 × 1.2 = 1.32 ✓. 3: 0.8 × 1.25 = 1 ✓. 4: 0.5% of 400 = 0.005 × 400 = 2, not 20 ✗. Three are correct.", "difficulty": "very-hard", "source": "SSC CGL"},
  {"id": "quant-percentage-38", "question": "A candidate needs 36% to pass. He scores 190 marks and fails by 26 marks. Another candidate scores 40% more marks than the first. By how many marks does the second candidate clear the pass mark?", "options": ["50", "40", "74", "26"], "answer": 0, "explanation": "Pass mark = 190 + 26 = 216 = 36% of maximum, so maximum = 600. Second candidate = 190 × 1.4 = 266. Margin = 266 − 216 = 50.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-percentage-39", "question": "What is 0.5% of 3,600?", "options": ["1.8", "72", "18", "180"], "answer": 2, "explanation": "0.5% = 0.5/100 = 1/200, so 3,600 ÷ 200 = 18. Reading 0.5% as 5% gives 180.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-percentage-40", "question": "Which is greater: 30% of 70 or 70% of 30?", "options": ["30% of 70", "70% of 30", "Cannot be determined", "Both are equal"], "answer": 3, "explanation": "x% of y = xy/100 = y% of x, so both equal 21.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-percentage-41", "question": "The fraction 5/16 expressed as a percentage is:", "options": ["31.25%", "30.25%", "31.5%", "32.5%"], "answer": 0, "explanation": "5/16 × 100 = 500/16 = 31.25%.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-percentage-42", "question": "The price of an appliance including 18% GST is ₹5,310. What is its price before GST?", "options": ["₹4,500", "₹4,354.20", "₹4,600", "₹4,400"], "answer": 0, "explanation": "Base × 1.18 = 5,310, so base = 5,310 ÷ 1.18 = ₹4,500. Taking 18% off ₹5,310 (₹4,354.20) is wrong because GST is 18% of the base, not of the final price.", "difficulty": "moderate", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-percentage-43", "question": "A bank raises its interest rate from 8% to 10% per annum. By what percent has the interest rate increased?", "options": ["25%", "20%", "2%", "10%"], "answer": 0, "explanation": "The rise is 2 percentage points, which is 2/8 × 100 = 25% of the old rate. 2% confuses percentage points with percent.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-percentage-44", "question": "Two numbers are 30% and 50% more than a third number. The first number is what percent of the second?", "options": ["80%", "84 1/3%", "60%", "86 2/3%"], "answer": 3, "explanation": "Take the third number as 100: the numbers are 130 and 150, and 130/150 × 100 = 86 2/3%. Subtracting 50 − 30 to say 80% ignores the different bases.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-percentage-45", "question": "If x% of 250 = 15% of 400 + 10% of 150, then x is:", "options": ["32", "25", "30", "35"], "answer": 2, "explanation": "15% of 400 = 60 and 10% of 150 = 15, so 2.5x = 75 and x = 30.", "difficulty": "moderate", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-percentage-46", "question": "A 60-litre mixture of milk and water contains 20% water. How much water must be added so that water becomes 25% of the new mixture?", "options": ["3 litres", "6 litres", "4 litres", "5 litres"], "answer": 2, "explanation": "Milk = 48 L stays fixed and must be 75% of the new mixture, so the new total is 48 ÷ 0.75 = 64 L; water added = 64 − 60 = 4 L. Adding 5% of 60 (3 L) ignores that the total also grows.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-percentage-47", "question": "When the numerator of a fraction is increased by 20% and its denominator is decreased by 10%, the fraction becomes 16/21. The original fraction is:", "options": ["4/7", "5/7", "2/3", "3/7"], "answer": 0, "explanation": "The fraction is multiplied by 1.2/0.9 = 4/3, so the original is 16/21 × 3/4 = 4/7.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-percentage-48", "question": "Fresh grapes contain 90% water by weight, while dried grapes contain 20% water. How much dried grapes can be obtained from 40 kg of fresh grapes?", "options": ["8 kg", "4 kg", "5 kg", "6 kg"], "answer": 2, "explanation": "The pulp is 10% of 40 = 4 kg and forms 80% of the dried grapes, so dried weight = 4 ÷ 0.8 = 5 kg. 4 kg forgets the 20% water still left in the dried grapes.", "difficulty": "hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-percentage-49", "question": "The length, breadth and height of a cuboid are changed by +20%, +10% and −25% respectively. Its volume:", "options": ["increases by 1%", "remains unchanged", "increases by 5%", "decreases by 1%"], "answer": 3, "explanation": "New volume factor = 1.2 × 1.1 × 0.75 = 0.99, a 1% decrease. Adding 20 + 10 − 25 = +5% is the classic slip; percentages multiply, they do not add.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-percentage-50", "question": "A family spends 60% of its budget on food and 40% on other items. Food prices rise by 15% and other prices by 10%. If the family buys the same quantities, by what percent does its total expenditure rise?", "options": ["13%", "13.5%", "25%", "12.5%"], "answer": 0, "explanation": "The rise is a weighted average: 0.6 × 15 + 0.4 × 10 = 9 + 4 = 13%. 12.5% is the simple average of 15 and 10, which ignores the weights.", "difficulty": "hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-percentage-51", "question": "If 60% of A equals 3/4 of B, and B is 20% of C, then A is what percent of C?", "options": ["30%", "25%", "20%", "16%"], "answer": 1, "explanation": "0.6A = 0.75B gives A = 1.25B, and B = 0.2C, so A = 1.25 × 0.2C = 0.25C, i.e. 25% of C.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-percentage-52", "question": "Income tax is nil on the first ₹3 lakh of income, 5% on the next ₹4 lakh and 10% on everything above ₹7 lakh. A person pays ₹38,000 as tax. What is his income?", "options": ["₹8.2 lakh", "₹9.6 lakh", "₹8.8 lakh", "₹7.6 lakh"], "answer": 2, "explanation": "Tax on the ₹4 lakh slab = ₹20,000, leaving ₹18,000 at 10%, i.e. ₹1.8 lakh above ₹7 lakh. Income = 3 + 4 + 1.8 = ₹8.8 lakh.", "difficulty": "hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-percentage-53", "question": "If x increases by 20% and y decreases by 20%, by what percent does x²y change?", "options": ["Increases by 12%", "Increases by 15.2%", "Increases by 4%", "Decreases by 4%"], "answer": 1, "explanation": "x²y is multiplied by 1.2² × 0.8 = 1.44 × 0.8 = 1.152, an increase of 15.2%. Ignoring the square gives 1.2 × 0.8 = 0.96, a 4% decrease.", "difficulty": "hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-percentage-54", "question": "In an election between two candidates, the loser got 45% of the votes and lost by 3,000 votes. Had 2,000 voters switched from the winner to the loser, the result would have been:", "options": ["the loser wins by 2,000 votes", "the loser wins by 500 votes", "the winner still wins by 1,000 votes", "the loser wins by 1,000 votes"], "answer": 3, "explanation": "10% of the votes = 3,000, so 30,000 votes were cast: 16,500 and 13,500. After the switch: 14,500 and 15,500, so the former loser wins by 1,000. Each switched vote changes the margin by 2, so the margin moves by 4,000.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-percentage-55", "question": "x is 20% of y and y is 25% of z. If z − x = 760, then y is:", "options": ["190", "240", "200", "160"], "answer": 2, "explanation": "x = 0.2 × 0.25z = 0.05z, so z − x = 0.95z = 760 and z = 800; y = 25% of 800 = 200.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-percentage-56", "question": "A student was asked to increase a number by 15% but decreased it by 15% instead. His answer was 54 less than the correct answer. What was the number?", "options": ["180", "360", "150", "270"], "answer": 0, "explanation": "The two answers differ by 15% + 15% = 30% of the number, so 0.3x = 54 and x = 180. Using only 15% gives 360.", "difficulty": "hard", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-percentage-57", "question": "How many of the following statements are correct?\n1. Successive increases of 20% and 30% equal a single increase of 56%.\n2. If a price falls by 20%, consumption must rise by 25% to keep expenditure unchanged.\n3. If A is 20% of B, then B is 400% more than A.\n4. A 10% increase in the radius of a circle increases its area by 20%.", "options": ["Only three", "Only two", "Only one", "All four"], "answer": 0, "explanation": "1: 1.2 × 1.3 = 1.56, true. 2: 20/80 = 25%, true. 3: B = 5A, i.e. 400% more, true. 4: 1.1² = 1.21, a 21% rise, so false.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-percentage-58", "question": "A town has a population of 1,20,000. Each year the population grows by 5% due to births and falls by 2% due to deaths, and 1,600 people emigrate at the end of each year. What is the population after 2 years?", "options": ["1,27,308", "1,24,060", "1,24,108", "1,23,960"], "answer": 1, "explanation": "Net growth is 3% a year. Year 1: 1,20,000 × 1.03 − 1,600 = 1,22,000. Year 2: 1,22,000 × 1.03 − 1,600 = 1,24,060. Subtracting 3,200 only at the end (1,24,108) forgets that the first year's emigrants do not grow.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-percentage-59", "question": "In an election among three candidates, 20% of the votes cast were invalid. The winner got 50% of the valid votes, the runner-up got 60% of the remaining valid votes and the third candidate got 4,800 votes. How many votes were cast in all?", "options": ["32,000", "30,000", "28,800", "24,000"], "answer": 1, "explanation": "The third candidate got 40% of the remaining 50%, i.e. 20% of valid votes = 4,800, so valid votes = 24,000. These are 80% of votes cast, so votes cast = 24,000 ÷ 0.8 = 30,000. 24,000 stops at the valid votes.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-percentage-60", "question": "A test has three papers with maximum marks 100, 150 and 250. A student scores 60% in the first paper and 70% in the second. What percent must he score in the third paper to get 72% overall?", "options": ["80%", "75%", "78%", "86%"], "answer": 2, "explanation": "He needs 72% of 500 = 360 marks; he has 60 + 105 = 165, so he needs 195 of 250 = 78%. 86% comes from averaging percentages (3 × 72 − 60 − 70), which ignores the unequal maximum marks.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-percentage-61", "question": "A's income is 20% more than B's. A saves 25% of his income and B saves 15% of his. If A's expenditure exceeds B's by ₹3,600, what is B's income?", "options": ["₹60,000", "₹72,000", "₹80,000", "₹48,000"], "answer": 1, "explanation": "Let B's income be x. A's expenditure = 0.75 × 1.2x = 0.9x and B's = 0.85x, so 0.05x = 3,600 and x = ₹72,000.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-percentage-62", "question": "In a town the male population rises by 5% and the female population by 8%, and the total population rises by 6.2%. What was the ratio of males to females originally?", "options": ["3 : 4", "3 : 2", "4 : 3", "2 : 3"], "answer": 1, "explanation": "5m + 8f = 6.2(m + f) gives 1.8f = 1.2m, so m : f = 1.8 : 1.2 = 3 : 2. (Alligation: (8 − 6.2) : (6.2 − 5) = 1.8 : 1.2.)", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-percentage-63", "question": "A phone's base price is ₹50,000 and GST of 28% is charged on it. In a sale, the base price is cut by 10% and the GST rate is reduced to 18%. How much does a buyer save on the final price?", "options": ["₹6,400", "₹10,900", "₹12,800", "₹9,900"], "answer": 1, "explanation": "Before: 50,000 × 1.28 = ₹64,000. After: 45,000 × 1.18 = ₹53,100. Saving = ₹10,900. Taking 20% off ₹64,000 (₹12,800) wrongly adds the 10% cut to the 10-point GST change.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-percentage-64", "question": "A 50-litre solution contains 40% alcohol. x litres are drawn off and replaced with water, and the process is repeated once more. The solution now contains 25.6% alcohol. What is x?", "options": ["8", "15", "12", "10"], "answer": 3, "explanation": "0.4(1 − x/50)² = 0.256, so (1 − x/50)² = 0.64, 1 − x/50 = 0.8 and x = 10.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-percentage-65", "question": "In a town of 50,000 people, 40% read newspaper A, 35% read B and 25% read C; 10% read A and B, 8% read B and C, 7% read A and C, and 3% read all three. How many people read none of the three?", "options": ["11,000", "9,500", "12,500", "14,000"], "answer": 0, "explanation": "At least one = 40 + 35 + 25 − 10 − 8 − 7 + 3 = 78%, so none = 22% of 50,000 = 11,000. Forgetting to add back the 3% gives 25% = 12,500.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-percentage-66", "question": "The radius of a sphere is increased by 10%. If its surface area increases by x% and its volume by y%, what is y − x?", "options": ["10", "12.1", "12", "9"], "answer": 1, "explanation": "Surface area ∝ r²: 1.1² = 1.21, so x = 21. Volume ∝ r³: 1.1³ = 1.331, so y = 33.1. y − x = 12.1.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-percentage-67", "question": "Assertion (A): If the price of an article falls by one-fifth, a buyer can increase his consumption by one-fourth without changing his expenditure.\nReason (R): After a decrease of x%, quantity must rise by 100x/(100 − x)% to keep expenditure constant.", "options": ["A is false but R is true", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "Both A and R are true, and R is the correct explanation of A"], "answer": 3, "explanation": "A fall of 1/5 = 20%, and by R the rise needed is 100 × 20/80 = 25% = 1/4. R is exactly the rule that proves A.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-percentage-68", "question": "A test has 200 questions, with +1 for a correct answer and −0.25 for a wrong one. A student attempts 80% of the questions and scores 50% of the maximum marks. What percent of his attempted questions were correct?", "options": ["56%", "62.5%", "75%", "70%"], "answer": 3, "explanation": "He attempts 160 and scores 100: c − 0.25(160 − c) = 100, so 1.25c = 140 and c = 112. Accuracy = 112/160 = 70%. 56% divides 112 by all 200 questions.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id":"quant-percentage-69","question":"If 125% of a number is 450, what is 80% of the same number?","options":["360","288","300","270"],"answer":1,"explanation":"The number is 450 ÷ 1.25 = 360, and 80% of 360 = 288. Shortcut: 80% ÷ 125% = 0.64, so 0.64 × 450 = 288.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-percentage-70","question":"Which of the following is the largest: 7/8, 85%, 0.86, 17/20?","options":["7/8","85%","0.86","17/20"],"answer":0,"explanation":"Convert all to decimals: 7/8 = 0.875, 85% = 0.85, 0.86 and 17/20 = 0.85. The largest is 7/8.","difficulty":"easy","source":"RRB NTPC · SSC CHSL"},
  {"id":"quant-percentage-71","question":"Suresh's monthly salary of ₹48,000 is raised by 15%, and then 10% of the new salary is deducted towards his provident fund. What is his take-home salary now?","options":["₹50,400","₹49,200","₹52,800","₹49,680"],"answer":3,"explanation":"Take-home = 48,000 × 1.15 × 0.9 = 48,000 × 1.035 = ₹49,680. Netting +15% and −10% as +5% (₹50,400) is the trap.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-percentage-72","question":"In a school, 45% of the students are girls. If 165 boys are absent on a day and they make up 25% of all the boys, what is the total strength of the school?","options":["1,100","1,320","1,200","1,500"],"answer":2,"explanation":"Boys = 165 ÷ 0.25 = 660, which is 55% of the strength. Total = 660 ÷ 0.55 = 1,200.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-percentage-73","question":"By what percent is 3/5 of 2/3 of a number less than 4/5 of the same number?","options":["40%","100%","50%","25%"],"answer":2,"explanation":"3/5 × 2/3 = 2/5, which is half of 4/5. So it is 50% less. 100% is the answer to 'by what percent is 4/5 more'.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-percentage-74","question":"A television is listed at ₹40,000. Shop P gives a 10% discount and then charges 18% GST on the discounted price. Shop Q adds 18% GST to the list price and then gives a 12% discount on the bill. How much more does Shop P charge than Shop Q?","options":["₹1,180","₹944","₹800","₹472"],"answer":1,"explanation":"P: 40,000 × 0.9 × 1.18 = ₹42,480. Q: 40,000 × 1.18 × 0.88 = ₹41,536. Difference = 40,000 × 1.18 × 0.02 = ₹944 — the order of discount and GST does not matter, only the discount rates do.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-percentage-75","question":"A panchayat ward has 25,000 voters. 10% of them did not vote, and 4% of the votes cast were invalid. In a two-candidate contest the winner got 55% of the valid votes. By how many votes did he win?","options":["2,160","2,250","2,500","2,025"],"answer":0,"explanation":"Valid votes = 25,000 × 0.9 × 0.96 = 21,600. Margin = (55 − 45)% of valid votes = 10% of 21,600 = 2,160. Taking 10% of votes cast (2,250) forgets the invalid votes.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-percentage-76","question":"The price of mustard oil rose by 25% in April and by a further x% in May. If the total rise over the two months is 50%, what is x?","options":["25","22.5","30","20"],"answer":3,"explanation":"1.25 × (1 + x/100) = 1.5, so 1 + x/100 = 1.2 and x = 20. Subtracting 50 − 25 = 25 ignores that May's rise is on a larger base.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-percentage-77","question":"In a recruitment test, Anil scores 30% more than Bimal, and Chitra scores 20% less than Anil. If Chitra scores 6 marks more than Bimal, what is Anil's score?","options":["150","156","180","195"],"answer":3,"explanation":"Chitra = 1.3 × 0.8 = 1.04 of Bimal, so 4% of Bimal = 6 and Bimal = 150. Anil = 1.3 × 150 = 195.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-percentage-78","question":"A town had a population of 2,40,000 in 2023. It rose by 5% in 2024, fell by 5% in 2025 and rose by 10% in 2026. What was the population at the end of 2026?","options":["2,64,000","2,63,000","2,63,340","2,62,500"],"answer":2,"explanation":"2,40,000 × 1.05 × 0.95 × 1.1. Note 1.05 × 0.95 = 0.9975 (not 1), so the answer is 2,64,000 × 0.9975 = 2,63,340.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-percentage-79","question":"After a 20% fall in the price of sugar, a household buys 6 kg more than it used to buy for ₹1,200 and still spends ₹120 less than ₹1,200. What is the new price of sugar per kg?","options":["₹25","₹20","₹18","₹22.50"],"answer":1,"explanation":"Let the old price be p, so old quantity = 1,200/p. New spend = 0.8p × (1,200/p + 6) = 960 + 4.8p = 1,080, giving p = 25. New price = 0.8 × 25 = ₹20.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-percentage-80","question":"A is 25% more than B, B is 40% less than C, and C exceeds A by 60. What is B?","options":["144","180","150","120"],"answer":0,"explanation":"B = 0.6C and A = 1.25 × 0.6C = 0.75C. C − A = 0.25C = 60, so C = 240 and B = 0.6 × 240 = 144.","difficulty":"hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-percentage-81","question":"A hospital has 40 litres of a sanitiser that is 70% alcohol. How much water must be added to bring the alcohol content down to 56%?","options":["10 litres","8 litres","12 litres","14 litres"],"answer":0,"explanation":"Alcohol stays at 28 L. For 56%, the total must be 28 ÷ 0.56 = 50 L, so add 10 L of water.","difficulty":"moderate","source":"SSC CHSL · RRB Group D"},
  {"id":"quant-percentage-82","question":"Neha pays 30% of her salary as rent, spends 20% of the rest on groceries and 25% of what then remains on a loan EMI. She saves the remaining ₹25,200. How much is her EMI?","options":["₹9,000","₹7,560","₹10,500","₹8,400"],"answer":3,"explanation":"Savings = 0.7 × 0.8 × 0.75 = 0.42 of salary, so salary = ₹60,000. EMI = 0.7 × 0.8 × 0.25 × 60,000 = ₹8,400 (one-third of the savings, since 25 : 75 = 1 : 3).","difficulty":"hard","source":"IBPS Clerk · SBI Clerk"},
  {"id":"quant-percentage-83","question":"A state's unemployment rate fell from 8% to 6% in a year. By what percent did the unemployment rate fall?","options":["2%","33.33%","25%","20%"],"answer":2,"explanation":"The fall is 2 percentage points, but as a percent of the old rate it is 2/8 × 100 = 25%. '2%' confuses percentage points with percent.","difficulty":"moderate","source":"SSC CGL · RBI Assistant"},
  {"id":"quant-percentage-84","question":"If x% of x is 36, what is x?","options":["6","60","36","600"],"answer":1,"explanation":"x × x/100 = 36, so x² = 3,600 and x = 60.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-percentage-85","question":"A number increased by 37.5% becomes 165. What does it become if it is instead decreased by 12.5%?","options":["120","105","144.375","110"],"answer":1,"explanation":"37.5% = 3/8, so the number = 165 × 8/11 = 120. Decreasing by 12.5% (1/8): 120 × 7/8 = 105.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-percentage-86","question":"A trader stores 1,000 kg of watermelons that are 99% water by weight. After a few days in the sun they are 98% water. What do they weigh now?","options":["500 kg","990 kg","980 kg","900 kg"],"answer":0,"explanation":"Dry matter = 1% of 1,000 = 10 kg and does not change. Now it is 2% of the weight, so weight = 10 ÷ 0.02 = 500 kg. A 1-point drop in water halves the weight.","difficulty":"very-hard","source":"SSC CGL · CAT-style"},
  {"id":"quant-percentage-87","question":"On a voters' list, 30% of the voters are women. If 80% of the men and 60% of the women cast their votes, what percentage of the voters on the list voted?","options":["70%","72%","76%","74%"],"answer":3,"explanation":"Weighted: 0.7 × 80 + 0.3 × 60 = 56 + 18 = 74%. The plain average of 80 and 60 (70%) ignores that there are more men.","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk"},
  {"id":"quant-percentage-88","question":"A's salary is 40% of B's and B's salary is 75% of C's. If the three together earn ₹82,000, what is A's salary?","options":["₹30,000","₹16,000","₹12,000","₹15,000"],"answer":2,"explanation":"With C = 100: B = 75 and A = 40% of 75 = 30. Total = 205 parts = ₹82,000, so one part = 400 and A = 30 × 400 = ₹12,000.","difficulty":"hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-percentage-89","question":"A single increase equivalent to three successive increases of 10%, 20% and 30% is:","options":["60%","66%","71.6%","72.6%"],"answer":2,"explanation":"1.1 × 1.2 × 1.3 = 1.716, i.e. a 71.6% increase. Adding the rates (60%) ignores the compounding.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-percentage-90","question":"In a factory 60% of the workers are skilled and earn ₹800 a day, while the rest earn ₹500 a day. If skilled wages rise by 5% and unskilled wages by 20%, by about what percent does the daily wage bill rise?","options":["11%","9.4%","12.5%","8.6%"],"answer":1,"explanation":"Per 10 workers: bill = 6 × 800 + 4 × 500 = ₹6,800. Rise = 6 × 40 + 4 × 100 = ₹640, and 640/6,800 ≈ 9.4%. Averaging 5% and 20% by headcount (11%) forgets the different wages.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-percentage-91","question":"A's salary rises by 20% every year (on the previous year's salary). B starts ₹10,000 above A and gets a fixed raise of ₹6,000 every year. After two years their salaries are equal. What was A's starting salary?","options":["₹50,000","₹55,000","₹45,000","₹60,000"],"answer":0,"explanation":"After 2 years A has 1.44A and B has A + 10,000 + 12,000. So 0.44A = 22,000 and A = ₹50,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-percentage-92","question":"Mohan's income rises by 20% and his expenditure by 30%, yet his savings rise by 10%. What percentage of his income did he save originally?","options":["40%","60%","45%","50%"],"answer":3,"explanation":"Take income 100 and savings s: 120 − 1.3(100 − s) = 1.1s gives 0.2s = 10, so s = 50%. Alligation check: the 20% rise in income lies midway between 10% and 30%, so savings and spending are equal.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-percentage-93","question":"A power board charges ₹5 per unit for the first 100 units, ₹7 per unit for the next 100 units and ₹10 per unit beyond 200 units, plus a 5% surcharge on the whole amount. If a bill is ₹2,100, how many units were consumed?","options":["300","260","290","280"],"answer":3,"explanation":"Before surcharge: 2,100 ÷ 1.05 = ₹2,000. The first 200 units cost 500 + 700 = ₹1,200, leaving ₹800 = 80 units at ₹10. Total 280 units.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"quant-percentage-94","question":"What is 40% of 3/5 of 750?","options":["300","225","180","450"],"answer":2,"explanation":"3/5 of 750 = 450, and 40% of 450 = 180. Or directly 0.4 × 0.6 = 0.24, and 0.24 × 750 = 180.","difficulty":"easy","source":"SSC CHSL · RRB Group D"},
  {"id":"quant-percentage-95","question":"The ratio of A to B is 3 : 5. By what percent is A less than B?","options":["66.67%","40%","60%","25%"],"answer":1,"explanation":"A is 2 less than B on a base of 5: 2/5 × 100 = 40%. 66.67% is B's excess over A.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-percentage-96","question":"When a number is decreased by 25% and 40 is then added, the result equals the number increased by 15%. What is the number?","options":["100","80","120","160"],"answer":0,"explanation":"0.75x + 40 = 1.15x, so 0.4x = 40 and x = 100.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-percentage-97","question":"In a district, 1,000 students appeared in the board exam in 2025 and 1,200 in 2026. The pass percentages were 75% and 80% respectively. What was the overall pass percentage for the two years together?","options":["77.5%","78%","76.36%","77.73%"],"answer":3,"explanation":"Passes = 750 + 960 = 1,710 out of 2,200 = 77.73%. The simple average 77.5% ignores that 2026 had more students.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-percentage-98","question":"The difference between 78% and 57% of a number is 3,276. What is 65% of the number?","options":["15,600","9,828","10,920","10,140"],"answer":3,"explanation":"21% of the number = 3,276, so 1% = 156 and 65% = 65 × 156 = 10,140.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk"},
  {"id":"quant-percentage-99","question":"In a term exam, Ravi's marks in Maths are 20% more than in Science, and his English marks are 10% less than his Maths marks. If his total in the three subjects is 246, what did he score in English?","options":["90","75","81","84"],"answer":2,"explanation":"With Science = 100: Maths = 120, English = 108, total 328. One unit = 246/328 = 0.75, so English = 108 × 0.75 = 81.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-percentage-100","question":"If 20% of (A + B) equals 30% of (A − B), A is what percent of B?","options":["250%","500%","150%","400%"],"answer":1,"explanation":"0.2A + 0.2B = 0.3A − 0.3B gives 0.1A = 0.5B, so A = 5B, i.e. 500% of B.","difficulty":"hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-percentage-101","question":"A vendor at a railway station sells 40% of his water bottles in the morning, 25% of the remaining in the afternoon and 30% of what is left in the evening. If 63 bottles remain, how many did he start with?","options":["200","180","210","250"],"answer":0,"explanation":"Fraction left = 0.6 × 0.75 × 0.7 = 0.315. Start = 63 ÷ 0.315 = 200. Adding 40 + 25 + 30 = 95% sold is the trap.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"quant-percentage-102","question":"A student's aggregate in 5 papers of 100 marks each was 72%. Later he got 10 grace marks in each of two papers, and his marks in another paper, entered as 58, were corrected to 85. What is his corrected percentage?","options":["81.4%","76%","78.6%","80.2%"],"answer":0,"explanation":"Total was 360. Add 20 grace marks and 85 − 58 = 27 for the correction: 407/500 = 81.4%.","difficulty":"hard","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-percentage-103","question":"12.5% of A is equal to 20% of B, and B is ₹4,800 less than A. What is A + B?","options":["₹12,800","₹19,200","₹16,000","₹20,800"],"answer":3,"explanation":"A/B = 20/12.5 = 8/5. The difference is 3 parts = 4,800, so 1 part = 1,600 and A + B = 13 parts = ₹20,800.","difficulty":"hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-percentage-104","question":"In a college library, 35% of the books are in Hindi, 45% in English and the rest in regional languages. 20% of the Hindi, 30% of the English and 50% of the regional books are reference books. If there are 1,830 reference books, how many books does the library have?","options":["6,100","5,500","6,000","6,500"],"answer":2,"explanation":"Reference share = 0.35 × 20 + 0.45 × 30 + 0.20 × 50 = 7 + 13.5 + 10 = 30.5%. Total = 1,830 ÷ 0.305 = 6,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-percentage-105","question":"The price of petrol goes up by 25%. By what percent must a car's mileage (km per litre) improve so that the fuel cost per km stays the same?","options":["20%","25%","12.5%","30%"],"answer":1,"explanation":"Cost per km = price ÷ mileage. To cancel a ×1.25 in price, mileage must also be ×1.25, i.e. improve by 25%. 20% is the cut needed in litres used, not the rise in mileage.","difficulty":"hard","source":"SSC CGL · CDS"},
  {"id":"quant-percentage-106","question":"In a two-candidate election the loser got 35% of the valid votes and lost by 7,500 votes. If 1,500 votes were invalid, how many votes were cast?","options":["25,000","26,500","23,500","28,000"],"answer":1,"explanation":"Margin = 65% − 35% = 30% of valid votes = 7,500, so valid votes = 25,000. Votes cast = 25,000 + 1,500 = 26,500.","difficulty":"hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-percentage-107","question":"The price of a commercial LPG cylinder rises by 15%. A dhaba cuts its gas use by 10%, but its monthly gas bill still rises by ₹1,050. What was its monthly gas bill earlier?","options":["₹30,000","₹21,000","₹35,000","₹20,000"],"answer":0,"explanation":"New bill = 1.15 × 0.9 = 1.035 of the old, a 3.5% rise. 3.5% = ₹1,050, so the old bill = ₹30,000. Taking the rise as 5% gives ₹21,000.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-percentage-108","question":"A student was asked to find 8/5 of a number but found 5/8 of it instead. What is the percentage error in his answer?","options":["39%","62.5%","156%","60.9375%"],"answer":3,"explanation":"Error = (8/5 − 5/8) ÷ 8/5 = (64 − 25)/64 = 39/64 = 60.9375%. The error is always measured against the correct value.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-percentage-109","question":"A cricket team won 60% of its first 30 matches in a season. How many of the remaining 20 matches must it win to finish the season with a 70% win record?","options":["18","14","17","20"],"answer":2,"explanation":"Wins so far = 18. For 70% of 50 matches it needs 35 wins, so 35 − 18 = 17 more.","difficulty":"hard","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-percentage-110","question":"A's marks are 25% of the total of B's and C's marks, and B's marks are 40% of the total of A's and C's marks. If C scored 360, what did A score?","options":["150","126","140","160"],"answer":2,"explanation":"A = 0.25B + 90 and B = 0.4A + 144. Substituting: A = 0.1A + 36 + 90, so 0.9A = 126 and A = 140 (B = 200; check 0.25 × 560 = 140).","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS"},
  {"id":"quant-percentage-111","question":"A number is increased by 10%, the result is decreased by 10%, and that result is increased by 20%. The final value is 37.6 more than the original number. What is the number?","options":["188","200","240","160"],"answer":1,"explanation":"Multiplier = 1.1 × 0.9 × 1.2 = 1.188, an 18.8% rise. 18.8% = 37.6, so the number is 200.","difficulty":"hard","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-percentage-112","question":"In a two-candidate election, if 10% of the winner's votes had gone to the loser instead, the loser would have won by 40 votes. If 1,840 valid votes were polled, by how many votes did the winner actually win?","options":["160","200","80","120"],"answer":0,"explanation":"L + 0.1W = 0.9W + 40, so L = 0.8W + 40. Then W + 0.8W + 40 = 1,840 gives W = 1,000 and L = 840. Actual margin = 160.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-percentage-113","question":"A earns 25% more than B. A spends 80% of his income, while B saves 30% of his. If B saves ₹1,500 more than A, what is A's income?","options":["₹30,000","₹40,000","₹36,000","₹37,500"],"answer":3,"explanation":"A saves 20% of 1.25B = 0.25B; B saves 0.3B. So 0.05B = 1,500, B = ₹30,000 and A = 1.25 × 30,000 = ₹37,500.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-percentage-114","question":"In a class, 60% of the students are boys. 25% of the boys and 40% of the girls scored above 90. Roughly what percentage of the students scoring above 90 are girls?","options":["40%","61.5%","48.4%","51.6%"],"answer":3,"explanation":"Per 100 students: boys above 90 = 15, girls = 16. Girls' share = 16/31 ≈ 51.6%. 40% is the girls' share of the class, not of the toppers.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-percentage-115","question":"A company's revenue grows by 20% and its costs grow by 10%. If profit was earlier 20% of revenue, by what percent does profit grow?","options":["10%","30%","60%","50%"],"answer":2,"explanation":"Take revenue 100 and cost 80, so profit 20. New profit = 120 − 88 = 32, a rise of 12 on 20 = 60%. Small changes in revenue and cost magnify profit change.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"quant-percentage-116","question":"A man loses 20% of his money, then gains 20% on what is left, and then spends ₹40. He now has ₹440. How much did he start with?","options":["₹480","₹500","₹520","₹550"],"answer":1,"explanation":"Before spending he had ₹480 = 0.8 × 1.2 = 0.96 of the start. Start = 480 ÷ 0.96 = ₹500. A 20% loss followed by a 20% gain is a 4% net loss.","difficulty":"hard","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-percentage-117","question":"The pass mark in a test is 36%. Ravi scores 20% more than the pass mark and Sita scores 10% less than the pass mark. If Ravi scores 54 marks more than Sita, what are the maximum marks?","options":["500","450","540","600"],"answer":0,"explanation":"Ravi − Sita = 1.2P − 0.9P = 0.3P = 54, so the pass mark P = 180. Maximum = 180 ÷ 0.36 = 500.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-percentage-118","question":"The price of gold rises by 30% and a family cuts its gold purchase by 30%. What happens to its spending on gold?","options":["9% decrease","No change","9% increase","6% decrease"],"answer":0,"explanation":"Spending = price × quantity = 1.3 × 0.7 = 0.91, a 9% decrease. Equal opposite percentage changes always give a net loss of x²/100 %.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-percentage-119","question":"₹15,000 is what percent of ₹2.5 lakh?","options":["0.6%","16.67%","60%","6%"],"answer":3,"explanation":"₹2.5 lakh = ₹2,50,000. 15,000/2,50,000 × 100 = 6%. Miscounting the zeros in a lakh gives 0.6% or 60%.","difficulty":"easy","source":"RRB NTPC · SSC CHSL"},
  {"id":"quant-percentage-120","question":"If 15% of x equals 20% of y, what is x : y?","options":["3 : 4","15 : 20","4 : 3","2 : 3"],"answer":2,"explanation":"0.15x = 0.2y gives x/y = 0.2/0.15 = 4/3. The quantity with the smaller percentage is the larger number.","difficulty":"easy","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-percentage-121","question":"A number is increased by 30% and the result is then decreased by 30%. If the final value is 455, what was the number?","options":["455","500","520","650"],"answer":1,"explanation":"Multiplier = 1.3 × 0.7 = 0.91, so the number = 455 ÷ 0.91 = 500. Equal rise and fall always give a net fall of 30²/100 = 9%.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-percentage-122","question":"A firm has 900 employees, 30% of whom are women. If no one leaves, how many women must it hire so that women make up 40% of the staff?","options":["150","90","120","135"],"answer":0,"explanation":"(270 + w)/(900 + w) = 0.4 gives 270 + w = 360 + 0.4w, so 0.6w = 90 and w = 150. Hiring 90 ignores that the new hires also enlarge the total.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-percentage-123","question":"If a% of b is 30 and b% of c is 45, then c is what percent more than a?","options":["50%","15%","33.33%","150%"],"answer":0,"explanation":"ab = 3,000 and bc = 4,500, so c/a = 1.5. Hence c is 50% more than a.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS"},
  {"id":"quant-percentage-124","question":"Every week a reservoir loses 10% of its water to irrigation and then gains 5% of the remaining water from rain. After two such weeks it holds 89,302.5 kilolitres. How much did it hold at the start?","options":["95,000 kl","1,05,000 kl","98,000 kl","1,00,000 kl"],"answer":3,"explanation":"Weekly multiplier = 0.9 × 1.05 = 0.945. Start = 89,302.5 ÷ 0.945² = 89,302.5 ÷ 0.893025 = 1,00,000 kl.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"quant-percentage-125","question":"A 3 kg batch of laddoo mix is 40% sugar. How much sugar must be added to make the mix 50% sugar?","options":["0.3 kg","0.5 kg","0.6 kg","0.75 kg"],"answer":2,"explanation":"Sugar = 1.2 kg, other = 1.8 kg, which stays fixed. At 50% sugar the other part is also 50%, so the total = 3.6 kg and sugar to add = 0.6 kg.","difficulty":"moderate","source":"SSC CHSL · RRB Group D"},
  {"id":"quant-percentage-126","question":"Scheme A pays a salesperson 5% commission on all sales. Scheme B pays ₹2,000 fixed plus 3% commission on sales above ₹10,000. For a certain month's sales, Scheme B pays ₹800 more than Scheme A. What were the sales?","options":["₹40,000","₹45,000","₹50,000","₹35,000"],"answer":1,"explanation":"B − A = 2,000 + 0.03(S − 10,000) − 0.05S = 1,700 − 0.02S = 800, so S = ₹45,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-percentage-127","question":"In a city, 52% of the people are men. 60% of the men and 45% of the women are literate. If there are 13,200 illiterate women, what is the population of the city?","options":["44,000","50,000","55,000","48,000"],"answer":1,"explanation":"Illiterate women = 48% × 55% = 26.4% of the population. Population = 13,200 ÷ 0.264 = 50,000.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-percentage-128","question":"To pass, a candidate needs at least 40% in each of two papers (maximum 150 and 100 marks) and at least 50% in aggregate. If he scores 95 in the first paper, what is the minimum he needs in the second paper?","options":["40","30","50","45"],"answer":0,"explanation":"The aggregate rule needs only 125 − 95 = 30, but the paper-wise rule needs 40% of 100 = 40. Both must hold, so the minimum is 40.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"quant-percentage-129","question":"A water purifier removes 85% of the impurities present in each pass. After two passes the water has 45 ppm of impurities. What was the impurity level originally?","options":["300 ppm","1,800 ppm","2,250 ppm","2,000 ppm"],"answer":3,"explanation":"Each pass leaves 15%, so two passes leave 0.15² = 0.0225. Original = 45 ÷ 0.0225 = 2,000 ppm. Removing 170% in total is impossible, so 'subtract twice' is wrong.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-percentage-130","question":"A coaching institute raises its fee by 20% and its enrolment falls by 15%. Its fee collection goes up by ₹36,000. What was the collection before the change?","options":["₹7,20,000","₹12,00,000","₹18,00,000","₹3,60,000"],"answer":2,"explanation":"New collection = 1.2 × 0.85 = 1.02 of the old, a 2% rise. 2% = ₹36,000, so the old collection = ₹18,00,000. Taking net change as 20 − 15 = 5% gives ₹7,20,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-percentage-131","question":"A man's salary is cut by 20%. By what percent must the reduced salary be raised so that he gets 10% more than his original salary?","options":["30%","25%","37.5%","32.5%"],"answer":2,"explanation":"Take 100 → 80. He needs 110, a rise of 30 on 80 = 37.5%. Adding 20 + 10 = 30% uses the wrong base.","difficulty":"hard","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-percentage-132","question":"A 20-litre solution contains 25% acid. x litres of it are drawn off and replaced with pure acid, after which the solution is 40% acid. What is x?","options":["3","4","5","6"],"answer":1,"explanation":"Replacing x litres raises acid by x − 0.25x = 0.75x. Needed rise = (40 − 25)% of 20 = 3 L, so x = 3 ÷ 0.75 = 4.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-percentage-133","question":"A publisher cuts the price of a book by 25% and its sales rise by 40%. What happens to the revenue from the book?","options":["5% increase","15% increase","5% decrease","No change"],"answer":0,"explanation":"Revenue = price × sales = 0.75 × 1.4 = 1.05, a 5% increase. 40 − 25 = 15% ignores the product term (−10%).","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-percentage-134","question":"If x increases by 25% and y decreases by 20%, by what percent does x/y change?","options":["5% increase","45% increase","50% increase","56.25% increase"],"answer":3,"explanation":"x/y becomes 1.25/0.8 = 1.5625 times, a 56.25% increase. Dividing by 0.8 is a 25% boost, not 20%.","difficulty":"hard","source":"SSC CGL · CDS"},
  {"id":"quant-percentage-135","question":"In the first of two years a town's population grew by 8%. In the second year 5% of its residents moved out, and 6,000 new residents arrived. The population is now 1,08,600. What was it two years ago?","options":["96,000","1,05,000","98,000","1,00,000"],"answer":3,"explanation":"P × 1.08 × 0.95 + 6,000 = 1,08,600, so 1.026P = 1,02,600 and P = 1,00,000.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"quant-percentage-136","question":"Of three numbers, the first is 20% of the sum of the other two and the second is 30% of the sum of the other two. Roughly what percent of the sum of the first two is the third?","options":["50%","47%","151.6%","100%"],"answer":2,"explanation":"a = 0.2(S − a) gives a = S/6; b = 0.3(S − b) gives b = 3S/13. With S = 78: a = 13, b = 18, c = 47. So c/(a + b) = 47/31 ≈ 151.6%.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS"},
  {"id":"quant-percentage-137","question":"Income above ₹5 lakh is taxed at 20% (income up to ₹5 lakh is tax-free), and a 4% cess is charged on the tax. If a person's total tax including cess is ₹52,000, what is his income?","options":["₹7,60,000","₹7,50,000","₹7,10,000","₹2,50,000"],"answer":1,"explanation":"Tax before cess = 52,000 ÷ 1.04 = ₹50,000, which is 20% of ₹2,50,000 above the exemption. Income = 5 + 2.5 = ₹7.5 lakh.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"quant-percentage-138","question":"A number is 20% of a second number and 25% of a third number. The second number is what percent of the third?","options":["125%","80%","105%","45%"],"answer":0,"explanation":"a = 0.2b = 0.25c, so b = 1.25c, i.e. 125% of c.","difficulty":"hard","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-percentage-139","question":"A milkman has 40 litres of milk with 5% water. How much water must he add so that water makes up 24% of the mixture?","options":["10 litres","7.6 litres","8 litres","12 litres"],"answer":0,"explanation":"Pure milk = 38 L stays fixed and must be 76% of the new total: 38 ÷ 0.76 = 50 L. Water to add = 50 − 40 = 10 L.","difficulty":"hard","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-percentage-140","question":"A laptop costs ₹60,000. A buyer pays 25% down and the rest through a 'no-cost EMI', which carries a processing fee of 2% of the financed amount plus 18% GST on that fee. How much does he pay in all?","options":["₹60,900","₹61,080","₹61,200","₹61,062"],"answer":3,"explanation":"Financed = ₹45,000. Fee = 2% = ₹900, plus GST 18% of 900 = ₹162. Total = 60,000 + 900 + 162 = ₹61,062.","difficulty":"very-hard","source":"IBPS PO · SBI Clerk"},
  {"id":"quant-percentage-141","question":"A shop's footfall rises by 25%, but the share of visitors who buy falls from 12% to 10%. If the average bill rises by 8%, by what percent do sales change?","options":["21% increase","15% increase","12.5% increase","8% increase"],"answer":2,"explanation":"Sales = visitors × conversion × bill = 1.25 × (10/12) × 1.08 = 1.125. A fall from 12% to 10% is a 1/6 drop, not a 2% drop.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains"},
  {"id":"quant-percentage-142","question":"A phone battery loses 15% of its current charge every hour. Starting fully charged, after how many complete hours does the charge first fall below 50%?","options":["4","5","3","6"],"answer":1,"explanation":"0.85² = 0.7225, 0.85⁴ ≈ 0.522 and 0.85⁵ ≈ 0.444. So it first drops below 50% after 5 hours, not 50/15 ≈ 3.3.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-percentage-143","question":"p is 150% of q, and r is 60% of (p + q). Then (r − q) is what percent of p?","options":["50%","33.33%","25%","66.67%"],"answer":1,"explanation":"Take q = 100: p = 150, r = 0.6 × 250 = 150. r − q = 50, which is 50/150 = 33.33% of p.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
];

export default questions;
